function minWindow(arr, target) {
  const targetSet = new Set(target);
  let minLen = Infinity, minStart = 0;
  let left = 0, formed = 0;
  const windowCounts = {};
  for (let right = 0; right < arr.length; right++) {
    const char = arr[right];
    windowCounts[char] = (windowCounts[char] || 0) + 1;
    if (targetSet.has(char) && windowCounts[char] === 1) formed++;
    while (formed === targetSet.size) {
      if (right - left + 1 < minLen) {
        minLen = right - left + 1;
        minStart = left;
      }
      windowCounts[arr[left]]--;
      if (targetSet.has(arr[left]) && windowCounts[arr[left]] === 0) formed--;
      left++;
    }
  }
  return minLen === Infinity ? "" : arr.slice(minStart, minStart + minLen);
}
